<template><view class="account-page feature-page"><FeaturePageState :status="status" :error="error" @retry="load"/><template v-if="status==='ready'"><view class="account-card store-panel"><view class="panel-heading"><text>选择门店</text><button class="account-link" :disabled="submitting" @click="storeOpen=true">切换<image src="/static/common/icon-switch-arrows.png" mode="aspectFit"/></button></view><view v-if="selectedStore" class="store-body"><image v-if="selectedStore.coverUrl" :src="selectedStore.coverUrl" mode="aspectFill"/><view v-else class="store-symbol"><image src="/static/common/icon-store.png" mode="aspectFit"/></view><view><view class="store-title">{{selectedStore.name}} <text>{{selectedStore.number}}</text></view><text class="account-caption">{{selectedStore.address}}</text></view></view><EmptyState v-else text="暂无可申请门店"/></view><view class="account-card duration-panel"><view class="panel-heading">开通时长</view><view class="duration-options"><button v-for="option in data.durations" :key="option.id" :class="{selected:durationId===option.id}" :disabled="submitting" @click="selectDuration(option.id)">{{option.label}}</button></view><view class="quote-total">合计价格：<text>{{quoting?'试算中…':quote?`¥${money(quote.payableAmount)}`:'—'}}</text></view><text v-if="quoteError" class="account-error">{{quoteError}}</text><button v-if="quoteError||(!quote&&!quoting&&storeId&&durationId)" class="account-link" :disabled="submitting" @click="refreshQuote">重新试算</button><view v-if="data.agreement?.version && data.agreement.content.nodes.length" class="agreement-line"><checkbox-group @change="agreed=$event.detail.value.includes('yes')"><label><checkbox value="yes" :checked="agreed" :disabled="submitting" color="#008fff"/>已阅读并同意</label></checkbox-group><button class="account-link" @click="agreementOpen=true">《合店协议》</button></view><text v-else class="account-note">合店协议暂未发布{{isMock?'，当前仅可演示申请流程。':'，暂不能提交正式申请。'}}</text><text v-if="submitError" class="account-error">{{submitError}}</text><button class="primary" :disabled="submitting||quoting||!quote||(!isMock&&!agreed)" @click="submit">{{submitting?'提交中…':'提交开通申请'}}</button><button class="account-link my-applications" @click="openApplications">我的申请</button></view><view class="account-card benefits-panel"><view class="panel-heading centered">等级权益</view><ManagedRichContent :content="data.benefits"/></view></template><view v-if="storeOpen" class="feature-mask" @click.self="storeOpen=false"><view class="feature-sheet"><view class="panel-heading">切换门店<button class="close-feature" aria-label="关闭门店选择" @click="storeOpen=false"><image src="/static/common/icon-close.png" mode="aspectFit"/></button></view><scroll-view scroll-y class="store-options"><button v-for="store in data.stores" :key="store.id" class="store-option" @click="selectStore(store.id)"><view>{{store.name}} <text>{{store.number}}</text></view><text>{{store.address}}</text><image :src="store.id===storeId?'/static/common/icon-radio-checked.png':'/static/common/icon-radio-unchecked.png'" mode="aspectFit"/></button><EmptyState v-if="!data.stores.length" text="暂无可申请门店"/></scroll-view></view></view><view v-if="agreementOpen" class="feature-mask" @click.self="agreementOpen=false"><view class="feature-sheet"><view class="panel-heading">合店协议<button class="close-feature" aria-label="关闭协议" @click="agreementOpen=false"><image src="/static/common/icon-close.png" mode="aspectFit"/></button></view><scroll-view scroll-y class="store-options"><ManagedRichContent :content="data.agreement.content"/></scroll-view></view></view></view></template>
<script setup>
import {ref,computed} from 'vue'
import {onLoad,onUnload} from '@dcloudio/uni-app'
import {config} from '../../config'
import {useAuth} from '../../composables/useAuth'
import {useAsyncPage} from '../../composables/useAsyncPage'
import {getCostoreOptions,quoteCostore,submitCostoreApplication} from '../../services/exclusive'
import {money} from '../../features/exclusive/format'
import FeaturePageState from '../../components/FeaturePageState.vue'
import ManagedRichContent from '../../components/ManagedRichContent.vue'
import EmptyState from '../../components/EmptyState.vue'
useAuth()
const isMock=config.useMock,storeId=ref(''),durationId=ref(''),storeOpen=ref(false),agreementOpen=ref(false),agreed=ref(false),quote=ref(null),quoting=ref(false),quoteError=ref(''),submitError=ref(''),submitting=ref(false)
let epoch=0,active=true,attemptKey='',quoteReceivedAt=0
const {data,status,error,load}=useAsyncPage(async()=>{const result=await getCostoreOptions();if(!active)return result;storeId.value=result.stores.some(item=>item.id===storeId.value)?storeId.value:result.stores[0]?.id||'';durationId.value=result.durations.some(item=>item.id===durationId.value)?durationId.value:result.durations[0]?.id||'';await refreshQuote();return result},false)
const selectedStore=computed(()=>data.value?.stores.find(item=>item.id===storeId.value))
async function refreshQuote(){const current=++epoch;quote.value=null;attemptKey='';quoteError.value='';submitError.value='';if(!storeId.value||!durationId.value)return;quoting.value=true;try{const result=await quoteCostore(storeId.value,durationId.value);if(current===epoch&&active){quote.value=result;quoteReceivedAt=Date.now()}}catch(reason){if(current===epoch&&active)quoteError.value=reason.message}finally{if(current===epoch&&active)quoting.value=false}}
function selectStore(id){if(submitting.value)return;storeId.value=id;storeOpen.value=false;refreshQuote()}
function selectDuration(id){if(submitting.value||durationId.value===id)return;durationId.value=id;refreshQuote()}
function openApplications(){uni.navigateTo({url:'/pages/application/list'})}
async function submit(){if(submitting.value||quoting.value||!quote.value)return;const selected=quote.value;const current=epoch;submitError.value='';if(selected.expiresAt<=selected.serverTime+(Date.now()-quoteReceivedAt)){submitError.value='报价已过期，请重新试算';await refreshQuote();return}if(!isMock&&(!agreed.value||!data.value.agreement?.version)){submitError.value='请阅读并同意已发布的合店协议';return}submitting.value=true;if(!attemptKey)attemptKey=`costore-${Date.now()}-${Math.random().toString(36).slice(2)}`;try{const result=await submitCostoreApplication({quoteId:selected.id,idempotencyKey:attemptKey,agreementVersion:agreed.value?data.value.agreement?.version:null});if(!active||current!==epoch)return;if(!result?.application?.id)throw new Error('申请结果异常，请到我的申请确认');quote.value=null;uni.showModal({title:'申请已提交',content:result.mockOnly?'仅保存本地待审核记录，未付款、未签约、未开通。':'请到我的申请查看处理进度，提交申请不代表已开通。',showCancel:false,success:()=>{if(active)openApplications()}})}catch(reason){if(active&&current===epoch)submitError.value=reason.message||'提交失败，请重试'}finally{if(active)submitting.value=false}}
onLoad(load);onUnload(()=>{active=false;++epoch})
</script>
<style>@import '../../styles/account.css';@import '../../styles/exclusive.css';</style>
<style scoped>.store-panel,.duration-panel,.benefits-panel{padding:28rpx 24rpx}.panel-heading{font-size:calc(var(--feature-font,14px)*1.07143);font-weight:600;display:flex;align-items:center;justify-content:space-between;gap:16rpx;margin-bottom:24rpx}.panel-heading .account-link{display:flex;align-items:center;gap:10rpx}.panel-heading .account-link image{width:32rpx;height:32rpx}.store-body{display:flex;gap:18rpx;align-items:center}.store-body>image,.store-symbol{width:150rpx;height:150rpx;border-radius:10rpx;flex-shrink:0}.store-symbol{display:flex;align-items:center;justify-content:center;background:#444c6c}.store-symbol image{width:70rpx;height:70rpx}.store-body>view:last-child{flex:1;min-width:0}.store-title{font-size:calc(var(--feature-font,14px)*1.00000);line-height:1.6;overflow-wrap:anywhere}.store-title text{font-size:calc(var(--feature-font,14px)*0.92857);display:inline-block;padding:0 10rpx;border-radius:25rpx;background:#008cff}.duration-options{display:flex;gap:16rpx;flex-wrap:wrap}.duration-options button{flex:1;min-width:160rpx;background:#444c6c;color:#fff;padding:16rpx;font-size:calc(var(--feature-font,14px)*1.03571);border-radius:12rpx;margin:0;border:2rpx solid transparent}.duration-options .selected{border-color:#009fff;background:#062750;color:#20b6ff}.quote-total{margin:28rpx 0;background:#444c6c;border-radius:40rpx;padding:16rpx;text-align:center;font-size:calc(var(--feature-font,14px)*1.00000);color:#b9c7df}.quote-total text{color:#ff4c79;font-size:calc(var(--feature-font,14px)*1.14286)}.agreement-line{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;font-size:calc(var(--feature-font,14px)*0.92857);margin:28rpx 0;color:#a7b7d0}.my-applications{margin:26rpx auto 0}.centered{justify-content:center}.store-options{max-height:70vh}.store-option{position:relative;display:block;width:100%;padding:24rpx 64rpx 24rpx 16rpx;margin:0 0 18rpx;background:#454c6c;color:#fff;text-align:left;border-radius:14rpx;line-height:1.8;font-size:calc(var(--feature-font,14px)*1.00000)}.store-option>text{font-size:calc(var(--feature-font,14px)*0.92857);color:#aab9d3}.store-option image{position:absolute;right:16rpx;top:36rpx;width:36rpx;height:36rpx}</style>
